    /// <summary>
    /// Class to delete General journals from various companies
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        //Company Info
        CompanyInfo                             companyInfo;
        DataArea                                DataArea;

        //General Journal Table
        LedgerJournalTable                      ledgerJournalTable;
        LedgerJournalId                         journNum;
        int                                     counter = 0;
        
        ttsbegin;
        //Select from CompanyInfo
        while select DataArea from companyInfo
            where companyInfo.DataArea != 'dat'
        {
            //Change company after looping through a set of legal entities and search for journals that not posted and auto approved
            changecompany(companyInfo.DataArea)
            {
                delete_from ledgerjournaltable
                        where ledgerjournaltable.journalnum != null
                    && ledgerjournalTable.DataAreaId == companyInfo.DataArea
                    && ledgerjournaltable.workflowapprovalstatus == ledgerjournalwfapprovalstatus::approved
                    && !ledgerjournaltable.posted
                    //Only as specific set of journals to be deleted and those journal names are mentioned below.
                    && ledgerJournalTable.JournalName == 'GLGenJrn'
                    && (ledgerJournalTable.Name == 'P8 Inbox clearing jnl 09'
                        || ledgerJournalTable.Name == 'DecRecClearingCorp'
                        || ledgerJournalTable.Name == 'SR Dec 21 #08H Misc JE'
                        || ledgerJournalTable.Name == 'General Journal'
                        || ledgerJournalTable.Name == 'FY22P09 IC #03 - National Rebate Adj #2'
                        || ledgerJournalTable.Name == 'FY22P09 Jan22 Kotara MJ'
                        || ledgerJournalTable.Name == 'NSW P09 #6. Excess Rebates'
                        || ledgerJournalTable.Name == 'WR-CR Ullage Accrual_Reversing & Transfer P9 2021'
                        || ledgerJournalTable.Name == 'FY22 Jan22 Kenthurst MJ Armaguard'
                        || ledgerJournalTable.Name == 'WR-CR Doubtful Debts and ALM Imports_Transfer P9 2021'
                        || ledgerJournalTable.Name == 'WR-CR Freight In & Out_Reversing P9 2021'
                    || ledgerJournalTable.Name == 'WR-CR RDC Cross Stock JE_Transfer P09 2021');


                counter++;
            }
            //Show Journal names and the count of the journals being deleted with every journal being removed.
            info(strfmt("%1 has been deleted.%2 records deleted",ledgerjournaltable.journalnum,counter));
        }
        
        ttscommit;
    }
